import type { BankQuestion } from "@/lib/bank";

/** Child Development and Pedagogy (Child Development and Pedagogy): 114 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cdp-child-development-1","question":"The RTE Act, 2009 provides free and compulsory education for children aged:","options":["3–14 years","6–14 years","6–18 years","5–15 years"],"answer":1,"explanation":"It covers children aged 6 to 14.","difficulty":"easy"},
  {"id":"cdp-child-development-2","question":"RTE stands for:","options":["Right to Education","Rules of Teaching Excellence","Right to Employment","Reading, Teaching and Evaluation"],"answer":0,"explanation":"The Right of Children to Free and Compulsory Education Act, 2009.","difficulty":"easy"},
  {"id":"cdp-child-development-3","question":"Which thinker is associated with the stages of cognitive development?","options":["Jean Piaget","B. F. Skinner","Ivan Pavlov","Sigmund Freud"],"answer":0,"explanation":"Piaget described four stages of cognitive development.","difficulty":"easy"},
  {"id":"cdp-child-development-4","question":"The concept of the Zone of Proximal Development was given by:","options":["Piaget","Vygotsky","Kohlberg","Skinner"],"answer":1,"explanation":"Lev Vygotsky introduced the ZPD: what a learner can do with help but not yet alone.","difficulty":"moderate"},
  {"id":"cdp-child-development-5","question":"The theory of multiple intelligences was proposed by:","options":["Howard Gardner","Jean Piaget","Lawrence Kohlberg","B. F. Skinner"],"answer":0,"explanation":"Howard Gardner proposed it in 1983.","difficulty":"moderate"},
  {"id":"cdp-child-development-6","question":"The term “scaffolding” in learning is associated with:","options":["Piaget","Vygotsky","Kohlberg","Erikson"],"answer":1,"explanation":"Scaffolding, temporary support from a more capable person, comes from Vygotsky’s sociocultural theory.","difficulty":"moderate"},
  {"id":"cdp-child-development-7","question":"Object permanence develops during which of Piaget’s stages?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":0,"explanation":"Object permanence develops in the sensorimotor stage (0–2 years).","difficulty":"hard"},
  {"id":"cdp-child-development-8","question":"According to Piaget, abstract and hypothetical thinking develops in the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":3,"explanation":"The formal operational stage (11+ years) brings abstract and hypothetical reasoning.","difficulty":"hard"},
  {"id":"cdp-child-development-9","question":"Kohlberg’s theory deals with:","options":["Cognitive development","Moral development","Psychosocial development","Language development"],"answer":1,"explanation":"Kohlberg proposed three levels and six stages of moral development.","difficulty":"hard"},
  {"id":"cdp-child-development-10","question":"Operant conditioning was proposed by:","options":["Ivan Pavlov","B. F. Skinner","Edward Thorndike","Albert Bandura"],"answer":1,"explanation":"Skinner showed that behaviour is shaped by reinforcement and punishment; Pavlov’s is classical conditioning.","difficulty":"very-hard"},
  {"id":"cdp-child-development-11","question":"“Egocentrism” is a characteristic of which Piagetian stage?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":1,"explanation":"Pre-operational children (2–7) find it hard to see things from another person’s point of view.","difficulty":"very-hard"},
  {"id":"cdp-child-development-12","question":"Erik Erikson’s stage of “Industry vs Inferiority” corresponds to the age group:","options":["0–1 years","3–6 years","6–12 years","12–18 years"],"answer":2,"explanation":"Industry vs Inferiority covers the school years, about 6 to 12.","difficulty":"very-hard"},
  {"id":"cdp-child-development-13","question":"According to Piaget, the stage of development from birth to about 2 years is the:","options":["Pre-operational stage","Sensorimotor stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"Infants learn through senses and movement in the sensorimotor stage.","difficulty":"easy","source":"CTET · UPTET"},
  {"id":"cdp-child-development-14","question":"The Right to Education Act, 2009 makes education free and compulsory for children aged:","options":["3–6 years","6–14 years","5–15 years","6–18 years"],"answer":1,"explanation":"The RTE Act covers children from 6 to 14 years.","difficulty":"easy","source":"CTET · SUPER TET"},
  {"id":"cdp-child-development-15","question":"Vygotsky’s “Zone of Proximal Development” refers to the gap between what a child can do:","options":["Alone and with the help of a more capable person","At home and at school","In the morning and the evening","Verbally and in writing"],"answer":0,"explanation":"ZPD is the range of tasks a learner can do with guidance but not yet alone.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-16","question":"Howard Gardner is known for the theory of:","options":["Moral development","Multiple intelligences","Classical conditioning","Psychosocial development"],"answer":1,"explanation":"Gardner proposed several independent intelligences: linguistic, logical, spatial, musical and more.","difficulty":"moderate","source":"CTET · KVS"},
  {"id":"cdp-child-development-17","question":"Classical conditioning was demonstrated by Pavlov using:","options":["Rats in a box","Dogs and a bell","Pigeons","Children and a doll"],"answer":1,"explanation":"Pavlov paired a bell with food until the bell alone made dogs salivate.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-18","question":"A child who learns to read a word and then reads it again correctly a week later is showing which process of memory?","options":["Encoding","Storage","Retrieval","Forgetting"],"answer":2,"explanation":"Recalling stored information when needed is retrieval.","difficulty":"very-hard","source":"CTET · DSSSB"},
  {"id":"cdp-child-development-19","question":"At Kohlberg’s pre-conventional level, a child judges right and wrong mainly by:","options":["Social approval","Punishment and reward","Universal ethical principles","Law and order"],"answer":1,"explanation":"Pre-conventional morality is about avoiding punishment and getting rewards.","difficulty":"hard"},
  {"id":"cdp-child-development-20","question":"Which of these is an example of formative assessment?","options":["The board exam at the end of the year","Short quizzes with feedback during teaching","An entrance test","The final term exam"],"answer":1,"explanation":"Formative assessment happens during learning and is used to improve it.","difficulty":"hard"},
  {"id":"cdp-child-development-21","question":"Bruner’s three modes of representation are:","options":["Enactive, iconic, symbolic","Sensory, motor, verbal","Concrete, abstract, formal","Visual, auditory, kinaesthetic"],"answer":0,"explanation":"Enactive (action), iconic (images) and symbolic (language).","difficulty":"very-hard"},
  {"id":"cdp-child-development-22","question":"Wolfgang Köhler demonstrated “learning by insight” in experiments with:","options":["Cats","Dogs","Chimpanzees","Pigeons"],"answer":2,"explanation":"His chimpanzee Sultan joined sticks to reach a banana, showing sudden insight.","difficulty":"very-hard"},
  {"id":"cdp-child-development-23","question":"How many of these statements are correct? I. Piaget’s concrete operational stage covers roughly 7 to 11 years. II. Conservation develops in the concrete operational stage. III. Object permanence develops in the sensorimotor stage. IV. Abstract reasoning begins in the pre-operational stage.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Abstract reasoning belongs to the formal operational stage.","difficulty":"very-hard"},
  {"id":"cdp-child-development-24","question":"How many of these statements are correct? I. The RTE Act, 2009 came into force on 1 April 2010. II. It reserves 25% of entry-level seats in private unaided schools for disadvantaged children. III. It lets schools hold screening tests for admission.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. The Act bans screening procedures and capitation fees.","difficulty":"very-hard"},
  {"id":"cdp-child-development-25","question":"A child knows that a ball of clay rolled into a sausage still has the same amount of clay. According to Piaget, the child has acquired:","options":["Conservation","Object permanence","Egocentrism","Animism"],"answer":0,"explanation":"Conservation develops in the concrete operational stage (about 7 to 11 years).","difficulty":"very-hard"},
  {"id":"cdp-child-development-26","question":"Vygotsky’s Zone of Proximal Development is the gap between:","options":["What a child can do alone and what the child can do with guidance","A child’s mental age and chronological age","What a child knows and what the curriculum expects","A child’s performance at home and at school"],"answer":0,"explanation":"The ZPD is what a learner can do with help from a more knowledgeable other but not yet alone; scaffolding works inside it.","difficulty":"very-hard"},
  {"id":"cdp-child-development-27","question":"How many of these statements are correct? I. Kohlberg’s theory deals with moral development. II. Erikson proposed eight psychosocial stages. III. Piaget proposed five stages of cognitive development.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Piaget proposed four stages: sensorimotor, pre-operational, concrete operational and formal operational.","difficulty":"very-hard"},
  {"id":"cdp-child-development-28","question":"Which pair of theory and psychologist is NOT correctly matched?","options":["Classical conditioning – Pavlov","Social learning theory – Bandura","Multiple intelligences – Gardner","Trial-and-error learning – Skinner"],"answer":3,"explanation":"Trial-and-error learning, with the laws of effect, exercise and readiness, is Thorndike’s. Skinner gave operant conditioning.","difficulty":"very-hard","source":"CTET · KVS"},
  {"id":"cdp-child-development-29","question":"How many of these statements about Erikson’s theory are correct? I. Trust vs mistrust is the first stage. II. Identity vs role confusion belongs to adolescence. III. The stages end with adolescence. IV. Initiative vs guilt covers roughly 3 to 6 years.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Erikson’s eight stages run through the whole lifespan, ending with integrity vs despair in old age.","difficulty":"very-hard","source":"CTET · DSSSB"},
  {"id":"cdp-child-development-30","question":"The Right of Children to Free and Compulsory Education Act, 2009 gives effect to which Article of the Constitution?","options":["Article 14","Article 21A","Article 45","Article 51A"],"answer":1,"explanation":"Article 21A, inserted by the 86th Amendment (2002), makes elementary education a fundamental right; Article 45 now deals with early childhood care below six years.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-31","question":"According to Piaget, the stage of cognitive development from about 2 to 7 years is the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"The pre-operational stage (2–7 years) is marked by symbolic play, egocentrism and lack of conservation.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-32","question":"The “law of effect” in learning was proposed by:","options":["Pavlov","Skinner","Thorndike","Bandura"],"answer":2,"explanation":"Thorndike’s law of effect states that responses followed by satisfying consequences are strengthened; Skinner later built operant conditioning on this idea.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-33","question":"The 5+3+3+4 curricular structure for school education was recommended by:","options":["National Policy on Education, 1986","Right to Education Act, 2009","National Education Policy, 2020","Kothari Commission, 1966"],"answer":2,"explanation":"NEP 2020 replaces the 10+2 pattern with foundational (5 years), preparatory (3), middle (3) and secondary (4) stages covering ages 3 to 18.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-34","question":"The formula IQ = (Mental age ÷ Chronological age) × 100 was given by:","options":["Alfred Binet","William Stern","Lewis Terman","Charles Spearman"],"answer":1,"explanation":"William Stern proposed the intelligence quotient in 1912; Binet devised the mental-age scale and Terman popularised the IQ in the Stanford–Binet test.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-35","question":"According to Vygotsky, the most important tool for cognitive development is:","options":["Maturation","Language","Reinforcement","Physical play"],"answer":1,"explanation":"For Vygotsky, language and social interaction mediate thinking; private speech becomes inner speech that guides problem solving.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-36","question":"A child is generally regarded as “gifted” if the IQ is above:","options":["90","110","130","150"],"answer":2,"explanation":"An IQ of about 130 or more (two standard deviations above the mean of 100) is the usual threshold for giftedness.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-37","question":"An examination held at the end of a term to judge how much students have learnt is an example of:","options":["Formative assessment","Diagnostic assessment","Summative assessment","Placement assessment"],"answer":2,"explanation":"Summative assessment measures learning at the end of a unit or course; formative assessment happens during teaching to improve it.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-38","question":"Dyslexia is a learning disability that mainly affects:","options":["Reading","Arithmetic","Handwriting","Motor coordination"],"answer":0,"explanation":"Dyslexia affects reading and spelling; dyscalculia affects arithmetic, dysgraphia writing and dyspraxia motor coordination.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-39","question":"Under NEP 2020, the foundational stage covers children aged:","options":["3 to 6 years","3 to 8 years","6 to 10 years","5 to 8 years"],"answer":1,"explanation":"The foundational stage spans three years of pre-school (ages 3–6) plus classes 1 and 2 (ages 6–8).","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-40","question":"Kohlberg’s “good boy–good girl” orientation, where a child seeks approval of others, belongs to the:","options":["Pre-conventional level","Conventional level","Post-conventional level","Autonomous level"],"answer":1,"explanation":"Stage 3 (interpersonal conformity) is the first stage of the conventional level; stage 4 is law-and-order orientation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-41","question":"A toddler who has learnt the word “dog” sees a cow for the first time and calls it “dog”. In Piaget’s terms this is an example of:","options":["Accommodation","Assimilation","Equilibration","Conservation"],"answer":1,"explanation":"The child fits new experience into an existing schema (assimilation); creating a new schema for “cow” would be accommodation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-42","question":"Erikson’s stage of “autonomy vs shame and doubt” corresponds to the age range:","options":["Birth to 1 year","1 to 3 years","3 to 6 years","6 to 12 years"],"answer":1,"explanation":"Toddlers (1–3 years) learn self-control and independence; success gives autonomy, over-restriction gives shame and doubt.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-43","question":"The pupil–teacher ratio prescribed by the RTE Act for classes I to V is:","options":["25:1","30:1","35:1","40:1"],"answer":1,"explanation":"The Schedule to the RTE Act requires 30:1 for classes I–V (two teachers for up to 60 children) and 35:1 for classes VI–VIII.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-44","question":"Dyscalculia refers to a specific learning difficulty in:","options":["Reading","Spelling","Mathematics","Speaking"],"answer":2,"explanation":"Dyscalculia affects number sense and arithmetic; such children struggle with counting, place value and simple calculations.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-45","question":"A student who easily understands the moods and feelings of classmates shows, in Gardner’s theory, a high level of:","options":["Intrapersonal intelligence","Interpersonal intelligence","Naturalistic intelligence","Linguistic intelligence"],"answer":1,"explanation":"Interpersonal intelligence is sensitivity to others’ feelings and motives; intrapersonal intelligence is understanding one’s own emotions.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-46","question":"Bandura’s Bobo doll experiment demonstrated:","options":["Classical conditioning","Insight learning","Observational learning","Trial-and-error learning"],"answer":2,"explanation":"Children who watched an adult hit the doll imitated the aggression, showing that behaviour is learnt by observing models (social learning theory).","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-47","question":"Under the RTE Act, a child above six years who has never been admitted to a school shall be admitted to:","options":["Class I","A class appropriate to his or her age","A bridge course for one year first","A pre-primary class"],"answer":1,"explanation":"Section 4 provides age-appropriate admission with special training to help the child catch up with peers.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-48","question":"How many of these statements about Piaget’s theory are correct? I. The formal operational stage begins at about 11 years. II. Reversibility of thought is achieved in the concrete operational stage. III. Animism is a feature of the pre-operational stage. IV. Piaget held that learning precedes development.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: Piaget held that development precedes and limits learning; it is Vygotsky who argued that learning can lead development.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-49","question":"Assertion (A): Vygotsky stressed scaffolding by a more knowledgeable other. Reason (R): For Vygotsky, cognitive development is a socially mediated process.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because higher mental functions develop through interaction with capable others, support within the zone of proximal development (scaffolding) is central; R is the reason for A.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-50","question":"Match Kohlberg’s stages with their orientations: 1. Stage 1 2. Stage 2 3. Stage 4 4. Stage 6; a. Universal ethical principles b. Law and order c. Punishment and obedience d. Instrumental exchange (“what’s in it for me”)","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"Stage 1 punishment–obedience, stage 2 instrumental exchange, stage 3 good boy–good girl, stage 4 law and order, stage 5 social contract, stage 6 universal ethical principles.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-51","question":"Which of the following is NOT a principle of development?","options":["Development proceeds from head to toe (cephalocaudal)","Development proceeds from the centre of the body outward (proximodistal)","Development proceeds from specific to general","Development is a continuous process"],"answer":2,"explanation":"Development moves from general to specific: a baby waves its whole arm before it can grasp with its fingers.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-52","question":"How many of these statements about the RTE Act, 2009 are correct? I. It covers children aged 6 to 14 years. II. Section 12(1)(c) requires private unaided schools to admit at least 25% children from weaker sections in the entry class. III. No board examination may be held until the completion of elementary education. IV. Mild physical punishment is permitted as a last resort.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (Section 30 bars board exams). IV is wrong: Section 17 prohibits all physical punishment and mental harassment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-53","question":"How many of these statements about NEP 2020 are correct? I. It replaces the 10+2 structure with 5+3+3+4. II. It aims at a 100% Gross Enrolment Ratio in school education by 2030. III. It makes the mother tongue compulsory as the medium of instruction up to class 8. IV. It was approved by the Union Cabinet on 29 July 2020.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: NEP 2020 says the home language or mother tongue should be the medium “wherever possible” at least till class 5, preferably till class 8; it is a recommendation, not a compulsion.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-54","question":"In Maslow’s hierarchy, which need comes immediately above safety needs?","options":["Esteem needs","Self-actualisation","Belongingness and love needs","Physiological needs"],"answer":2,"explanation":"The order from the base is physiological → safety → belongingness and love → esteem → self-actualisation.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-55","question":"Assertion (A): A teacher should use formative assessment regularly during a unit. Reason (R): Formative assessment gives feedback that lets the teacher modify teaching while learning is still in progress.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Formative assessment is “assessment for learning”; its purpose is timely feedback, which is exactly why it should be continuous.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-56","question":"Match the psychologist with the concept: 1. Pavlov 2. Chomsky 3. Binet 4. Spearman; a. g-factor of intelligence b. Language acquisition device c. First intelligence test d. Classical conditioning","options":["1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c"],"answer":0,"explanation":"Pavlov → classical conditioning, Chomsky → innate language acquisition device, Binet → first practical intelligence test (1905), Spearman → two-factor (g and s) theory.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-57","question":"How many of these statements about theories of intelligence are correct? I. Spearman proposed the two-factor theory. II. Thurstone proposed seven primary mental abilities. III. The Binet–Simon scale was first published in 1905. IV. Sternberg’s triarchic theory includes analytical, creative and practical intelligence.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct; the common confusion is attributing multiple intelligences (Gardner) to Thurstone or the g-factor to Binet.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-58","question":"A four-year-old says her doll is “sad” because it fell down. According to Piaget, this illustrates:","options":["Conservation","Animism","Reversibility","Decentration"],"answer":1,"explanation":"Animism, attributing life and feelings to inanimate objects, is typical of the pre-operational stage; conservation and reversibility come later.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-59","question":"A student refuses to copy in an examination, saying “rules must be obeyed, otherwise there will be chaos in school”. In Kohlberg’s scheme the student is at:","options":["Stage 1, punishment and obedience","Stage 3, interpersonal conformity","Stage 4, law and order","Stage 5, social contract"],"answer":2,"explanation":"Reasoning that rules must be upheld to maintain social order is the law-and-order orientation (stage 4, conventional level); stage 1 would cite fear of punishment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-60", "question": "Inclusive education means:", "options": ["Separate schools for children with disabilities", "Educating all children, including those with disabilities, together in regular classrooms", "Admitting only high-achieving students", "Teaching only through the mother tongue"], "answer": 1, "explanation": "Inclusive education places every child, whatever their ability, background or disability, in the same classroom and adapts teaching to meet their needs.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-61", "question": "The idea of “learning by doing” is most closely associated with:", "options": ["B. F. Skinner", "Ivan Pavlov", "John Dewey", "Sigmund Freud"], "answer": 2, "explanation": "John Dewey, the pragmatist philosopher, held that children learn best through activity and real experience rather than passive listening.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-62", "question": "Kohlberg’s theory of moral development has:", "options": ["Three stages in one level", "Six stages grouped into three levels", "Eight stages in four levels", "Four stages in two levels"], "answer": 1, "explanation": "Kohlberg described pre-conventional, conventional and post-conventional levels, each with two stages, making six stages in all.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-63", "question": "Which of these is an example of intrinsic motivation?", "options": ["A student studies to get a prize", "A student reads storybooks because she enjoys reading", "A student works hard to avoid punishment", "A student studies to please his parents"], "answer": 1, "explanation": "Intrinsic motivation comes from interest and enjoyment of the activity itself. Prizes, punishment and approval of others are external (extrinsic) motivators.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-64", "question": "ADHD, a condition that affects a child’s attention and self-control in class, stands for:", "options": ["Attention Deficit Hyperactivity Disorder", "Auditory Development Hearing Disorder", "Acquired Developmental Handicap Disorder", "Attention Delay and Hearing Difficulty"], "answer": 0, "explanation": "Children with Attention Deficit Hyperactivity Disorder find it hard to sustain attention and may be impulsive or overactive; short tasks and structured routines help them.", "difficulty": "moderate", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-65", "question": "Continuous and comprehensive evaluation (CCE) of a child’s understanding is provided for in which law?", "options": ["The Right to Education Act, 2009", "The Rights of Persons with Disabilities Act, 2016", "The Juvenile Justice Act, 2015", "The National Commission for Protection of Child Rights Act, 2005"], "answer": 0, "explanation": "Section 29(2) of the RTE Act requires the curriculum and evaluation procedure to include comprehensive and continuous evaluation of the child’s understanding and ability to apply knowledge.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-66", "question": "According to Freud, the “id” operates on the:", "options": ["Reality principle", "Morality principle", "Pleasure principle", "Social principle"], "answer": 2, "explanation": "The id seeks immediate gratification (pleasure principle), the ego follows the reality principle, and the superego represents moral standards.", "difficulty": "moderate", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-67", "question": "In Piaget’s theory, a “schema” is:", "options": ["A punishment used to stop bad behaviour", "An organised pattern of thought or action used to understand the world", "A formal test of intelligence", "The gap between what a child can do alone and with help"], "answer": 1, "explanation": "Schemas are mental frameworks that are built and changed through assimilation and accommodation. The gap described in the last option is Vygotsky’s ZPD.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-68", "question": "Which intelligence did Howard Gardner add in 1995 as the eighth in his theory of multiple intelligences?", "options": ["Existential", "Naturalistic", "Emotional", "Spiritual"], "answer": 1, "explanation": "Gardner added naturalistic intelligence (recognising and classifying plants, animals and nature) in 1995. Existential intelligence has only been suggested as a possible ninth.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-69", "question": "Which of these is NOT one of Thorndike’s primary laws of learning?", "options": ["Law of readiness", "Law of exercise", "Law of effect", "Law of insight"], "answer": 3, "explanation": "Thorndike’s three primary laws are readiness, exercise and effect. Insight learning comes from Köhler and the Gestalt school.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-70", "question": "A teacher asks, “In how many ways can we use a brick?” This question mainly encourages:", "options": ["Convergent thinking", "Divergent thinking", "Rote memory", "Concrete operational thinking"], "answer": 1, "explanation": "Open-ended questions with many possible answers promote divergent (creative) thinking. Convergent thinking aims at one correct answer.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-71", "question": "According to Vygotsky, a child talking aloud to herself while solving a puzzle (private speech):", "options": ["Shows that she is egocentric and immature", "Helps her guide and regulate her own thinking", "Is a sign of a language disorder", "Should be stopped by the teacher at once"], "answer": 1, "explanation": "Vygotsky saw private speech as a tool of self-regulation that later becomes inner speech. Piaget, by contrast, called it egocentric speech.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-72", "question": "Which of the following is a projective test of personality?", "options": ["16PF questionnaire", "Rorschach inkblot test", "Stanford–Binet test", "Raven’s Progressive Matrices"], "answer": 1, "explanation": "In the Rorschach test the subject interprets ambiguous inkblots, projecting inner feelings. 16PF is a self-report inventory, while Stanford–Binet and Raven’s are intelligence tests.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-73", "question": "A test given to find the specific areas in which a student has learning difficulties is a:", "options": ["Diagnostic test", "Achievement test", "Aptitude test", "Placement test"], "answer": 0, "explanation": "A diagnostic test pinpoints the exact weaknesses so that remedial teaching can follow. An achievement test measures how much has been learnt.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-74", "question": "Arrange these levels of Bloom’s revised taxonomy from the lowest to the highest: 1. Applying 2. Remembering 3. Creating 4. Analysing", "options": ["2, 1, 4, 3", "2, 4, 1, 3", "1, 2, 4, 3", "2, 1, 3, 4"], "answer": 0, "explanation": "The revised taxonomy (Anderson and Krathwohl, 2001) runs Remembering → Understanding → Applying → Analysing → Evaluating → Creating, with Creating at the top.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-75", "question": "Assertion (A): Constructivist teaching discourages rote memorisation of facts. Reason (R): Constructivism holds that learners actively build knowledge by linking new experiences to what they already know.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because knowledge is constructed, not received, constructivists prefer activities, discussion and exploration over memorising. R explains A.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-76", "question": "Assertion (A): Boys and girls should be given different curricula because gender decides intellectual ability. Reason (R): Gender roles are largely shaped by society through socialisation.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: intellectual ability does not depend on gender, and separate curricula reinforce stereotypes. R is true: gender is a social construct learnt through family, school and media.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-77", "question": "Match the psychologist with the idea: 1. Albert Bandura 2. Jerome Bruner 3. David Ausubel 4. Wolfgang Köhler; a. Insight learning b. Meaningful verbal learning and advance organisers c. Discovery learning d. Social (observational) learning", "options": ["1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Bandura proposed social learning, Bruner discovery learning, Ausubel meaningful reception learning with advance organisers, and Köhler insight learning.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-78", "question": "Child A is 8 years old with a mental age of 10 years; child B is 10 years old with a mental age of 8 years. What is the difference between their IQs?", "options": ["20", "45", "25", "2"], "answer": 1, "explanation": "IQ = (MA ÷ CA) × 100. A: 10/8 × 100 = 125. B: 8/10 × 100 = 80. Difference = 125 − 80 = 45.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-79", "question": "Which of the following is NOT a feature of a child-centred classroom?", "options": ["Children learn through activities and discussion", "The teacher acts as a facilitator", "The textbook is treated as the only source of knowledge and the teacher as the sole authority", "Children’s experiences are linked to what is taught"], "answer": 2, "explanation": "Child-centred pedagogy uses many sources of learning and treats the teacher as a facilitator; seeing the textbook and teacher as the sole authority is the traditional, teacher-centred approach.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-80", "question": "How many of these statements about the Rights of Persons with Disabilities Act, 2016 are correct? I. It recognises 21 types of disabilities. II. It replaced the Persons with Disabilities Act, 1995. III. It gives every child with benchmark disability aged 6 to 18 years the right to free education. IV. Specific learning disabilities are not included among the specified disabilities.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: specific learning disabilities (such as dyslexia) are among the 21 specified disabilities, up from seven in the 1995 Act.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-81", "question": "How many of these statements are correct? I. Piaget saw the child as a “little scientist” who constructs knowledge. II. Vygotsky argued that learning leads development. III. Piaget held that language drives thought. IV. Vygotsky proposed four universal, fixed stages of cognitive development.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Piaget held that thought comes before language, and the four universal stages are Piaget’s idea; Vygotsky stressed culture and social interaction instead of fixed stages.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-82", "question": "A teacher excuses students from an extra written task whenever they listen attentively in class, and attentive listening increases. This is an example of:", "options": ["Positive reinforcement", "Negative reinforcement", "Punishment", "Extinction"], "answer": 1, "explanation": "Removing something unpleasant (the extra task) to strengthen a behaviour is negative reinforcement. Punishment weakens behaviour, so it is the common wrong answer.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-83", "question": "How many of these are examples of assessment for learning? I. Oral questions during a lesson followed by feedback II. Peer assessment of first drafts III. A year-end board examination IV. A portfolio reviewed with feedback during the term", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV give feedback while learning is going on, so they are assessment for learning (formative). A year-end board exam is assessment of learning (summative).", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-84", "question": "Arrange in chronological order: 1. National Curriculum Framework 2005 2. Right to Education Act 3. Kothari Commission report 4. National Education Policy 2020", "options": ["3, 2, 1, 4", "1, 3, 2, 4", "3, 1, 2, 4", "3, 1, 4, 2"], "answer": 2, "explanation": "Kothari Commission report 1966 → NCF 2005 → RTE Act 2009 → NEP 2020.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-85", "question": "Who described adolescence as a period of ‘storm and stress’?", "options": ["G. Stanley Hall", "John Dewey", "Sigmund Freud", "Jean Piaget"], "answer": 0, "explanation": "G. Stanley Hall, in his 1904 work on adolescence, called it a time of ‘storm and stress’ marked by emotional ups and downs. Later researchers found that not every adolescent goes through such turmoil.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-86", "question": "The ‘kindergarten’ (children’s garden) system of early education was started by:", "options": ["John Locke", "Rabindranath Tagore", "Friedrich Froebel", "Maria Montessori"], "answer": 2, "explanation": "Friedrich Froebel opened the first kindergarten in Germany in 1837, stressing play, songs and ‘gifts’ (educational toys). Montessori developed her own method later, around 1907.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-87", "question": "‘Emile’, the book that urged education according to the child’s nature, was written by:", "options": ["Jean-Jacques Rousseau", "John Dewey", "Johann Pestalozzi", "Plato"], "answer": 0, "explanation": "Rousseau’s ‘Emile’ (1762) argued that children should learn through nature and experience at their own pace, an early root of child-centred education.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-88", "question": "Development of control proceeding from the head towards the feet, so that a baby controls its head before its legs, is called the:", "options": ["Cephalocaudal principle", "Principle of individual differences", "Principle of integration", "Proximodistal principle"], "answer": 0, "explanation": "Cephalocaudal means ‘head to tail’. The proximodistal principle describes development from the centre of the body outward, for example arm control before finger control.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-89", "question": "The Montessori method of education places the greatest emphasis on:", "options": ["Self-directed learning with specially designed sensory materials", "Rote learning under strict teacher control", "Competitive examinations from an early age", "Learning only through stories told by the teacher"], "answer": 0, "explanation": "Montessori classrooms give children self-correcting materials that train the senses, so they learn by themselves (auto-education) while the teacher observes and guides.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-90", "question": "The theory that an infant’s early emotional bond with a caregiver shapes later relationships is the attachment theory of:", "options": ["John Bowlby", "Lawrence Kohlberg", "Edward Thorndike", "B. F. Skinner"], "answer": 0, "explanation": "John Bowlby argued that a secure attachment to a responsive caregiver gives the child a safe base from which to explore. Mary Ainsworth later studied attachment types with the ‘strange situation’ test.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-91", "question": "Parents who are warm and responsive but also set clear rules and explain them follow which parenting style, according to Diana Baumrind?", "options": ["Authoritative", "Authoritarian", "Permissive", "Neglectful"], "answer": 0, "explanation": "Authoritative parenting combines high warmth with high control and is linked with confident, self-reliant children. Authoritarian parents are strict but cold, and permissive parents are warm but set few limits.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-92", "question": "A ‘spiral curriculum’, in which topics are revisited at increasing levels of depth, was proposed by:", "options": ["Jean Piaget", "Jerome Bruner", "Abraham Maslow", "Ivan Pavlov"], "answer": 1, "explanation": "Bruner held that any subject can be taught in some honest form to any child, and then revisited in more complex forms as the child grows.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-93", "question": "The ‘forgetting curve’, showing that most forgetting happens soon after learning, was given by:", "options": ["Wolfgang Köhler", "Hermann Ebbinghaus", "Albert Bandura", "Howard Gardner"], "answer": 1, "explanation": "Ebbinghaus tested his own memory of nonsense syllables and found a steep early drop in retention that later levels off. This is why regular revision soon after learning helps.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-94", "question": "A child who calls every four-legged animal ‘dog’ learns that cows are different and forms a new category for them. In Piaget’s terms, the child has shown:", "options": ["Conservation", "Object permanence", "Assimilation", "Accommodation"], "answer": 3, "explanation": "Accommodation is changing an existing schema or making a new one when new experience does not fit. Calling the cow ‘dog’ in the first place would have been assimilation.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-95", "question": "Carol Gilligan criticised Kohlberg’s theory of moral development mainly because she felt it:", "options": ["Had too few stages", "Was based largely on male subjects and overlooked an ‘ethic of care’", "Ignored the role of rewards", "Was meant only for adults"], "answer": 1, "explanation": "Gilligan argued that Kohlberg’s justice-based stages, drawn mostly from boys, undervalued moral reasoning based on care and relationships, which she found more often in women.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-96", "question": "J. P. Guilford’s ‘Structure of Intellect’ model classifies intellectual abilities along which three dimensions?", "options": ["Operations, contents and products", "Fluid, crystallised and general", "Analytical, creative and practical", "Verbal, numerical and spatial"], "answer": 0, "explanation": "Guilford crossed operations (such as cognition and divergent production), contents and products to produce many distinct abilities. Analytical, creative and practical belong to Sternberg, and fluid–crystallised to Cattell.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-97", "question": "The idea of ‘emotional intelligence’ was popularised by whose 1995 book?", "options": ["Alfred Binet", "Robert Sternberg", "Howard Gardner", "Daniel Goleman"], "answer": 3, "explanation": "Daniel Goleman’s ‘Emotional Intelligence’ (1995) spread the concept, first proposed by Salovey and Mayer, of recognising and managing one’s own and others’ emotions.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-98", "question": "A child who has learnt to ride a bicycle finds it easier to learn to ride a scooter. This is an example of:", "options": ["Retroactive inhibition", "Zero transfer", "Negative transfer", "Positive transfer"], "answer": 3, "explanation": "Positive transfer occurs when earlier learning helps new learning because the skills share elements such as balance. Negative transfer is when earlier learning gets in the way.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-99", "question": "The NIPUN Bharat Mission, launched in July 2021, aims to ensure that every child achieves:", "options": ["Proficiency in English by Class 5", "Digital literacy by Class 8", "Vocational skills by Class 10", "Foundational literacy and numeracy by the end of Class 3"], "answer": 3, "explanation": "NIPUN Bharat (National Initiative for Proficiency in Reading with Understanding and Numeracy) targets foundational literacy and numeracy by the end of Grade 3, with 2026–27 as the target year.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-100", "question": "‘Action research’ was introduced into education to help teachers solve their own classroom problems by:", "options": ["B. F. Skinner", "Jean Piaget", "Kurt Lewin, applied to schools by Stephen M. Corey", "Lev Vygotsky"], "answer": 2, "explanation": "Kurt Lewin coined the term, and Stephen M. Corey popularised action research in education in the 1950s as a way for teachers to study and improve their own practice.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-101", "question": "Paulo Freire criticised the ‘banking concept’ of education, in which:", "options": ["The teacher deposits information into passive students", "Students save marks for later examinations", "Students are taught how to manage money", "Schools are run like banks for profit"], "answer": 0, "explanation": "In ‘Pedagogy of the Oppressed’ Freire argued against treating learners as empty accounts to be filled, and called for dialogue and critical thinking instead.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-102", "question": "A student who learnt French last year keeps mixing up French words while learning Spanish this year. This is an example of:", "options": ["Positive transfer", "Proactive interference", "Decay", "Retroactive interference"], "answer": 1, "explanation": "In proactive interference old learning disrupts the recall of new learning. If the new Spanish words made the student forget French, that would be retroactive interference.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-103", "question": "How many of these statements about the principles of development are correct? I. Development is a continuous process. II. Development proceeds from the centre of the body outward. III. All children develop at the same rate. IV. Development results from the interaction of heredity and environment.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct; II is the proximodistal principle. III is wrong: development follows a similar sequence in all children, but its rate differs from child to child.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-104", "question": "Match the learning difficulty with the area it mainly affects: 1. Dyslexia 2. Dysgraphia 3. Dyspraxia 4. Dysphasia; a. Language and speech b. Motor coordination c. Writing d. Reading", "options": ["1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b"], "answer": 2, "explanation": "Dyslexia affects reading, dysgraphia writing, dyspraxia the planning and coordination of movement, and dysphasia the use and understanding of spoken language.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-105", "question": "Assertion (A): Teachers should avoid labelling children as ‘slow learners’ or ‘failures’. Reason (R): Labels can lower a child’s self-concept and teachers’ expectations, which can then become a self-fulfilling prophecy.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Studies of the Pygmalion effect show that children tend to perform as teachers expect, so a negative label can push achievement down. That is why R explains A.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-106", "question": "A student argues: ‘Laws are agreements made by people for the common good; if a law violates basic rights, it should be changed through democratic means.’ In Kohlberg’s scheme this reasoning belongs to:", "options": ["Stage 5, social contract orientation", "Stage 2, instrumental exchange", "Stage 3, good boy–good girl orientation", "Stage 4, law and order orientation"], "answer": 0, "explanation": "Seeing laws as changeable social contracts that should protect rights is Stage 5 (post-conventional). Stage 4 treats laws as fixed rules to be obeyed to keep order.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-107", "question": "How many of these statements are correct? I. PARAKH was set up as a national assessment centre under the NCERT. II. The National Curriculum Framework for the Foundational Stage (2022) covers children aged 6 to 14. III. Vidya Pravesh is a three-month play-based school-preparation module for children entering Grade 1. IV. The National Curriculum Framework for School Education (2023) was drafted by a committee headed by Dr K. Kasturirangan.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. II is wrong: the foundational stage covers ages 3 to 8 (three years of pre-school plus Grades 1 and 2).", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-108", "question": "Arrange in chronological order: 1. Bandura’s Bobo doll experiments 2. Gardner proposes multiple intelligences 3. Binet–Simon intelligence scale 4. Skinner publishes ‘The Behavior of Organisms’", "options": ["3, 4, 1, 2", "3, 4, 2, 1", "3, 1, 4, 2", "4, 3, 1, 2"], "answer": 0, "explanation": "The Binet–Simon scale came in 1905, Skinner’s book on operant conditioning in 1938, the Bobo doll studies in 1961 and Gardner’s ‘Frames of Mind’ in 1983.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-109", "question": "A student who fails a test says, ‘I was just unlucky today.’ According to Weiner’s attribution theory, the student has attributed the failure to a cause that is:", "options": ["External, stable and controllable", "External, unstable and uncontrollable", "Internal, stable and uncontrollable", "Internal, unstable and controllable"], "answer": 1, "explanation": "Luck lies outside the person, changes from day to day and cannot be controlled. Lack of effort would be internal, unstable and controllable, and low ability internal, stable and uncontrollable.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-110", "question": "Match the defence mechanism with its example: 1. Rationalisation 2. Projection 3. Displacement 4. Regression; a. An older child starts sucking his thumb after a sibling is born b. A child scolded by the teacher kicks his little brother at home c. A dishonest pupil accuses classmates of cheating d. A boy who is not chosen for the team says he never wanted to play anyway", "options": ["1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Rationalisation gives a convenient excuse (sour grapes), projection puts one’s own faults on others, displacement vents feelings on a safer target, and regression is a return to earlier, childish behaviour.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-111", "question": "Which of the following is NOT usually a characteristic of a creative child?", "options": ["Preference for a single, fixed correct answer", "Curiosity and asking unusual questions", "Tolerance for ambiguity", "Divergent thinking"], "answer": 0, "explanation": "Creative children produce many original ideas and are comfortable with open-ended problems. Looking for one fixed answer is convergent thinking, which tests of creativity do not reward.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-112", "question": "Assertion (A): Gifted children do not need any special educational provision because they can learn on their own. Reason (R): Gifted children have exceptional abilities that need enrichment or acceleration to develop fully.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false and R is true. Without challenge, gifted children may become bored, underachieve or develop behaviour problems, so they need enrichment, acceleration or ability-appropriate tasks.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-113", "question": "How many of these statements about intelligence tests are correct? I. The Stanford–Binet test is an individual test. II. The WISC was developed by David Wechsler. III. Raven’s Progressive Matrices is a verbal test. IV. Bhatia’s Battery is a verbal test of intelligence.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Raven’s Progressive Matrices is a non-verbal, culture-reducing test of abstract reasoning, and C. M. Bhatia’s Battery is a set of performance tests designed for Indian children.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-114", "question": "Arrange Bronfenbrenner’s environmental systems from the innermost to the outermost around the child: 1. Exosystem 2. Microsystem 3. Macrosystem 4. Mesosystem", "options": ["2, 1, 4, 3", "2, 4, 3, 1", "2, 4, 1, 3", "4, 2, 1, 3"], "answer": 2, "explanation": "The microsystem (family, school) is closest; the mesosystem links microsystems (home–school); the exosystem affects the child indirectly (a parent’s workplace); the macrosystem is the wider culture. The chronosystem adds change over time.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
];

export default questions;
